def opcode_stack_effect(op: ast) -> tuple[operand_stack_height, operand_stack_height]:
    match op:
        case STOP(None):
            return (0, 0)
        case ADD(None):
            return (2, 1)
        case MUL(None):
            return (2, 1)
        case SUB(None):
            return (2, 1)
        case DIV(None):
            return (2, 1)
        case SDIV(None):
            return (2, 1)
        case MOD(None):
            return (2, 1)
        case SMOD(None):
            return (2, 1)
        case ADDMOD(None):
            return (3, 1)
        case MULMOD(None):
            return (3, 1)
        case EXP(None):
            return (2, 1)
        case SIGNEXTEND(None):
            return (2, 1)
        case LT(None):
            return (2, 1)
        case GT(None):
            return (2, 1)
        case SLT(None):
            return (2, 1)
        case SGT(None):
            return (2, 1)
        case EQ(None):
            return (2, 1)
        case ISZERO(None):
            return (1, 1)
        case AND(None):
            return (2, 1)
        case OR(None):
            return (2, 1)
        case XOR(None):
            return (2, 1)
        case NOT(None):
            return (1, 1)
        case BYTE(None):
            return (2, 1)
        case SHL(None):
            return (2, 1)
        case SHR(None):
            return (2, 1)
        case SAR(None):
            return (2, 1)
        case CLZ(None):
            return (1, 1)
        case KECCAK256(None):
            return (2, 1)
        case ADDRESS(None):
            return (0, 1)
        case BALANCE(None):
            return (1, 1)
        case ORIGIN(None):
            return (0, 1)
        case CALLER(None):
            return (0, 1)
        case CALLVALUE(None):
            return (0, 1)
        case CALLDATALOAD(None):
            return (1, 1)
        case CALLDATASIZE(None):
            return (0, 1)
        case CALLDATACOPY(None):
            return (3, 0)
        case CODESIZE(None):
            return (0, 1)
        case CODECOPY(None):
            return (3, 0)
        case GASPRICE(None):
            return (0, 1)
        case EXTCODESIZE(None):
            return (1, 1)
        case EXTCODECOPY(None):
            return (4, 0)
        case RETURNDATASIZE(None):
            return (0, 1)
        case RETURNDATACOPY(None):
            return (3, 0)
        case EXTCODEHASH(None):
            return (1, 1)
        case BLOCKHASH(None):
            return (1, 1)
        case COINBASE(None):
            return (0, 1)
        case TIMESTAMP(None):
            return (0, 1)
        case NUMBER(None):
            return (0, 1)
        case PREVRANDAO(None):
            return (0, 1)
        case GASLIMIT(None):
            return (0, 1)
        case CHAINID(None):
            return (0, 1)
        case SELFBALANCE(None):
            return (0, 1)
        case BASEFEE(None):
            return (0, 1)
        case BLOBHASH(None):
            return (1, 1)
        case BLOBBASEFEE(None):
            return (0, 1)
        case SLOTNUM(None):
            return (0, 1)
        case POP(None):
            return (1, 0)
        case MLOAD(None):
            return (1, 1)
        case MSTORE(None):
            return (2, 0)
        case MSTORE8(None):
            return (2, 0)
        case SLOAD(None):
            return (1, 1)
        case SSTORE(None):
            return (2, 0)
        case JUMP(None):
            return (1, 0)
        case JUMPI(None):
            return (2, 0)
        case PC(None):
            return (0, 1)
        case MSIZE(None):
            return (0, 1)
        case GAS(None):
            return (0, 1)
        case JUMPDEST(None):
            return (0, 0)
        case TLOAD(None):
            return (1, 1)
        case TSTORE(None):
            return (2, 0)
        case MCOPY(None):
            return (3, 0)
        case PUSH((_, _)):
            return (0, 1)
        case DUP(n):
            return (n, (int(n) + 1))
        case SWAP(n):
            return ((int(n) + 1), (int(n) + 1))
        case DUPN(immediate):
            if deep_stack_immediate_valid(immediate):
                n = decode_single_stack_index(immediate)
                return (n, (int(n) + 1))
            else:
                return (0, 0)
        case SWAPN(immediate):
            if deep_stack_immediate_valid(immediate):
                n = decode_single_stack_index(immediate)
                return ((int(n) + 1), (int(n) + 1))
            else:
                return (0, 0)
        case EXCHANGE(immediate):
            if exchange_immediate_valid(immediate):
                (_, higher) = decode_exchange_stack_indices(immediate)
                return ((int(higher) + 1), (int(higher) + 1))
            else:
                return (0, 0)
        case LOG(n):
            return ((int(n) + 2), 0)
        case opcode_CREATE(None):
            return (3, 1)
        case CALL(None):
            return (7, 1)
        case CALLCODE(None):
            return (7, 1)
        case RETURN(None):
            return (2, 0)
        case DELEGATECALL(None):
            return (6, 1)
        case CREATE2(None):
            return (4, 1)
        case STATICCALL(None):
            return (6, 1)
        case REVERT(None):
            return (2, 0)
        case INVALID(None):
            return (0, 0)
        case SELFDESTRUCT(None):
            return (1, 0)
        case _:
            raise SailMatchFailure("no Sail match clause applied")

